package com.tekwatt.user.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="rfid_cards")public class RfidCard{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,unique=true,length=64)private String cardUid;@Column(length=120)private String label;private UUID userId;@Column(length=500)private String notes;@Column(nullable=false,length=20)private String status;@Column(nullable=false)private Instant issuedAt;private Instant revokedAt;protected RfidCard(){}public RfidCard(UUID t,String uid,String l,UUID u,String n){id=UUID.randomUUID();tenantId=t;cardUid=uid;label=l;userId=u;notes=n;status="ACTIVE";issuedAt=Instant.now();}public void status(String s){status=s;if("REVOKED".equals(s))revokedAt=Instant.now();}public void assign(UUID u){userId=u;}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public String getCardUid(){return cardUid;}public String getLabel(){return label;}public UUID getUserId(){return userId;}public String getNotes(){return notes;}public String getStatus(){return status;}public Instant getIssuedAt(){return issuedAt;}public Instant getRevokedAt(){return revokedAt;}}
